refentry.refsect1:
&reftitle.description;
arrayarray_map callablenullcallback arrayarray arrayarrays
array_map ले callback का लागि arguments का रूपमा प्रयोग गरिएका array (र थप arrays प्रदान गरिएको भए arrays) का सम्बन्धित value मा callback लागू गर्दा आउने परिणामहरू समावेश भएको एउटा &array; return गर्दछ। callback function ले स्वीकार गर्ने parameters को संख्या array_map मा pass गरिएका arrays को संख्यासँग मेल खानुपर्छ। अतिरिक्त input arrays लाई ignore गरिन्छ। यदि अपर्याप्त संख्यामा arguments प्रदान गरियो भने एउटा ArgumentCountError throw गरिन्छ।

  &reftitle.returnvalues;

callback का लागि arguments का रूपमा प्रयोग गरिएका array (र थप arrays प्रदान गरिएमा arrays) का सम्बन्धित value मा callback function लागू गर्दा प्राप्त परिणामहरू समावेश भएको एउटा array return गर्दछ।

यदि र केवल यदि ठीक एउटा array pass गरिएको छ भने मात्र return गरिएको array ले array argument का keys सुरक्षित राख्नेछ। यदि एउटाभन्दा बढी array pass गरियो भने, return गरिएको array मा sequential integer keys हुनेछन्।

  &reftitle.examples;



    array_map को उदाहरण


<?php
function cube($n)
{
    return ($n * $n * $n);
}

$a = [1, 2, 3, 4, 5];
$b = array_map('cube', $a);
print_r($b);
?>



यसले गर्दा $b मा निम्न मान हुन्छ:


Array
(
    [0] => 1
    [1] => 8
    [2] => 27
    [3] => 64
    [4] => 125
)







    lambda function प्रयोग गरेर array_map


<?php
$func = function(int $value): int {
    return $value * 2;
};

print_r(array_map($func, range(1, 5)));

// Or as of PHP 7.4.0:

print_r(array_map(fn($value): int => $value * 2, range(1, 5)));

?>


    &example.outputs;


Array
(
    [0] => 2
    [1] => 4
    [2] => 6
    [3] => 8
    [4] => 10
)
Array
(
    [0] => 2
    [1] => 4
    [2] => 6
    [3] => 8
    [4] => 10
)







    array_map - थप arrays प्रयोग गरेर


<?php
function show_Spanish(int $n, string $m): string
{
    return "The number {$n} is called {$m} in Spanish";
}

function map_Spanish(int $n, string $m): array
{
    return [$n => $m];
}

$a = [1, 2, 3, 4, 5];
$b = ['uno', 'dos', 'tres', 'cuatro', 'cinco'];

$c = array_map('show_Spanish', $a, $b);
print_r($c);

$d = array_map('map_Spanish', $a , $b);
print_r($d);
?>


    &example.outputs;


// printout of $c
Array
(
    [0] => The number 1 is called uno in Spanish
    [1] => The number 2 is called dos in Spanish
    [2] => The number 3 is called tres in Spanish
    [3] => The number 4 is called cuatro in Spanish
    [4] => The number 5 is called cinco in Spanish
)

// printout of $d
Array
(
    [0] => Array
        (
            [1] => uno
        )

    [1] => Array
        (
            [2] => dos
        )

    [2] => Array
        (
            [3] => tres
        )

    [3] => Array
        (
            [4] => cuatro
        )

    [4] => Array
        (
            [5] => cinco
        )

)





सामान्यतया दुई वा दुईभन्दा बढी arrays प्रयोग गर्दा तिनीहरू समान लम्बाइका हुनुपर्छ, किनभने callback function सम्बन्धित elements मा समानान्तर रूपमा लागू गरिन्छ। यदि arrays असमान लम्बाइका छन् भने, सबैभन्दा लामोको लम्बाइसँग मिलाउन छोटाहरूलाई खाली elements थपेर विस्तार गरिनेछ।

यो function को एउटा चाखलाग्दो प्रयोग arrays को एउटा array निर्माण गर्नु हो, जुन callback function को नामको रूपमा &null; प्रयोग गरेर सजिलै गर्न सकिन्छ।



    arrays को zip operation गर्ने


<?php
$a = [1, 2, 3, 4, 5];
$b = ['one', 'two', 'three', 'four', 'five'];
$c = ['uno', 'dos', 'tres', 'cuatro', 'cinco'];

$d = array_map(null, $a, $b, $c);
print_r($d);
?>


    &example.outputs;


Array
(
    [0] => Array
        (
            [0] => 1
            [1] => one
            [2] => uno
        )

    [1] => Array
        (
            [0] => 2
            [1] => two
            [2] => dos
        )

    [2] => Array
        (
            [0] => 3
            [1] => three
            [2] => tres
        )

    [3] => Array
        (
            [0] => 4
            [1] => four
            [2] => cuatro
        )

    [4] => Array
        (
            [0] => 5
            [1] => five
            [2] => cinco
        )

)








    केवल array सँग &null; callback


<?php
$array = [1, 2, 3];
var_dump(array_map(null, $array));
?>


    &example.outputs;


array(3) {
  [0]=>
  int(1)
  [1]=>
  int(2)
  [2]=>
  int(3)
}







    array_map - string keys सहित


<?php
$arr = ['stringkey' => 'value'];
function cb1($a) {
    return [$a];
}
function cb2($a, $b) {
    return [$a, $b];
}
var_dump(array_map('cb1', $arr));
var_dump(array_map('cb2', $arr, $arr));
var_dump(array_map(null,  $arr));
var_dump(array_map(null, $arr, $arr));
?>


    &example.outputs;


array(1) {
  ["stringkey"]=>
  array(1) {
    [0]=>
    string(5) "value"
  }
}
array(1) {
  [0]=>
  array(2) {
    [0]=>
    string(5) "value"
    [1]=>
    string(5) "value"
  }
}
array(1) {
  ["stringkey"]=>
  string(5) "value"
}
array(1) {
  [0]=>
  array(2) {
    [0]=>
    string(5) "value"
    [1]=>
    string(5) "value"
  }
}




    array_map - associative arrays

array_map ले array key लाई input को रूपमा प्रयोग गर्न प्रत्यक्ष समर्थन नगरे पनि, array_keys प्रयोग गरेर त्यसलाई simulate गर्न सकिन्छ।


<?php
$arr = [
    'v1' => 'First release',
    'v2' => 'Second release',
    'v3' => 'Third release',
];

// Note: Before 7.4.0, use the longer syntax for anonymous functions instead.
$callback = fn(string $k, string $v): string => "$k was the $v";

$result = array_map($callback, array_keys($arr), array_values($arr));

var_dump($result);
?>


    &example.outputs;


array(3) {
  [0]=>
  string(24) "v1 was the First release"
  [1]=>
  string(25) "v2 was the Second release"
  [2]=>
  string(24) "v3 was the Third release"
}
